async function clearFeats(actor){const ids=actor.items.filter(it=>it.getFlag(FS,ITEM_FLAG)).map(it=>it.id);if(ids.length)await actor.deleteEmbeddedDocuments("Item",ids);}

async function doCommune(actor){
  const echo=getEcho(actor),n=Math.max(0,3-echo);
  await clearFeats(actor);
  const pool=ancEntries(),p=[...pool],drawn=[];
  for(let i=0;i<n&&p.length;i++)drawn.push(p.splice(Math.floor(Math.random()*p.length),1)[0]);
  if(drawn.length)await actor.createEmbeddedDocuments("Item",drawn.map(e=>makeData(e,false)));
  await actor.setFlag(FS,F_DRAW,drawn.map(e=>e.code));
  await actor.setFlag(FS,F_OVER,[]);
  const list=drawn.map(e=>'<b>'+e.code+'·'+e.name+'</b>').join('、')||'<i>无人应召</i>';
  const flavor=n===0?'群声喧嚣，先祖们各执其声，今日竟无人应你而醒——你只能越界相求了。':('月桂顶端的星辰次第睁眼，'+drawn.length+'位先祖随你同行。');
  ChatMessage.create({speaker:ChatMessage.getSpeaker({actor}),content:'<div style="font-family:Signika,sans-serif;background:#0d1f12;border:2px solid #2e7d32;border-radius:8px;padding:11px 12px;color:#d7f5dd;"><div style="color:#7be89a;font-size:15px;font-weight:bold;margin-bottom:5px;">群灵议会 · 今日通灵</div><div style="font-size:12.5px;line-height:1.6;">'+flavor+'</div><div style="font-size:12.5px;margin-top:6px;">回响 <b>'+echo+'</b>　·　今日苏醒 <b>'+n+'</b> 位：'+list+'</div></div>'});
  openWheel(actor);
}
async function doOverdraw(actor,code){
  const pool=ancEntries(),e=pool.find(x=>x.code===code);if(!e)return;
  const draw=getDraw(actor),over=getOver(actor);
  if(draw.includes(code)){ui.notifications.info(e.code+"·"+e.name+" 今日已苏醒，无需越界。");return;}
  if(over.includes(code)){ui.notifications.warn("你今日已越界呼唤过 "+e.code+"·"+e.name+"，同一位先祖不能重复呼唤。");return;}
  await actor.createEmbeddedDocuments("Item",[makeData(e,true)]);
  over.push(code);await actor.setFlag(FS,F_OVER,over);
  const echo=getEcho(actor)+1;await actor.setFlag(FS,F_ECHO,echo);
  ChatMessage.create({speaker:ChatMessage.getSpeaker({actor}),content:'<div style="font-family:Signika,sans-serif;background:#160d20;border:2px solid #6a4fb0;border-radius:8px;padding:11px 12px;color:#e7d7f5;"><div style="color:#c4a9ff;font-size:15px;font-weight:bold;margin-bottom:5px;">越界 · 呼唤沉睡的先祖</div><div style="font-size:12.5px;line-height:1.6;">'+actor.name+'以一个附赠动作越过苏醒的界限，将沉睡的 <b>'+e.code+'·'+e.name+'</b> 唤到场前。你随后可按其能力本身的动作消耗发动它一次。</div><div style="font-size:12px;margin-top:6px;color:#b39ddb;">回响 +1（当前 <b>'+echo+'</b>）。明日苏醒将少一位；回响需于长休祭祀先祖以消解。</div></div>'});
