  const html='<style>#lw-wrap{font-family:Signika,sans-serif;background:radial-gradient(circle at 50% 42%,#13301c 0%,#0a1810 70%,#060d09 100%);color:#d7f5dd;border-radius:10px;padding:10px;display:flex;gap:12px;}#lw-stage{position:relative;width:440px;height:440px;flex:0 0 440px;}#lw-ring{position:absolute;inset:0;transform-origin:220px 220px;animation:lwspin 110s linear infinite;will-change:transform;}#lw-stage:hover #lw-ring{animation-play-state:paused;}@keyframes lwspin{to{transform:rotate(360deg);}}#lw-core{position:absolute;left:50%;top:50%;width:60px;height:60px;margin:-30px 0 0 -30px;border-radius:50%;cursor:pointer;background:radial-gradient(circle,#fff7cf 0%,#9be86a 45%,#2e7d32 100%);box-shadow:0 0 28px 9px rgba(155,232,106,.7),0 0 64px 20px rgba(46,125,50,.45);animation:lwcore 3.4s ease-in-out infinite;}@keyframes lwcore{0%,100%{transform:scale(1);}50%{transform:scale(1.08);}}.lw-wrap{position:absolute;width:0;height:0;animation:lwdrift var(--dur,5s) ease-in-out infinite;will-change:transform;}@keyframes lwdrift{0%,100%{transform:translate(0,0);}50%{transform:translate(var(--dx,0),var(--dy,0));}}@keyframes lwtwinkle{0%,100%{opacity:.62;}50%{opacity:1;}}@keyframes lwpulse{0%,100%{transform:scale(1);}50%{transform:scale(1.32);}}.lw-dot{position:absolute;left:0;top:0;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;cursor:pointer;transition:transform .12s;}.lw-dim{background:radial-gradient(circle,#3a7a4a,#16361f);box-shadow:0 0 4px 1px rgba(58,122,74,.5);}.lw-awake{background:radial-gradient(circle,#eafff0,#5dff8f 55%,#1f9e44);box-shadow:0 0 12px 4px rgba(93,255,143,.9);}.lw-over{background:radial-gradient(circle,#f3e6ff,#c4a9ff 55%,#6a4fb0);box-shadow:0 0 11px 4px rgba(160,120,230,.85);}.lw-dot:hover{transform:scale(1.55)!important;z-index:5;}.lw-sel{outline:2px solid #fff7cf;outline-offset:2px;}#lw-side{flex:1;min-width:240px;display:flex;flex-direction:column;}#lw-bar{display:flex;gap:8px;margin-bottom:8px;font-size:12.5px;}#lw-bar .pill{background:#0e2616;border:1px solid #2e7d32;border-radius:6px;padding:4px 10px;flex:1;text-align:center;}#lw-info{flex:1;background:#0e2616;border:1px solid #2e7d32;border-radius:8px;padding:12px;min-height:150px;overflow:auto;max-height:300px;}#lw-info h3{margin:0 0 2px;color:#9be86a;font-size:16px;}#lw-info .ttl{font-size:12px;color:#7fae8b;margin-bottom:8px;}#lw-info .body{font-size:12.5px;line-height:1.6;color:#cdeccf;}#lw-info .body p{margin:5px 0;}#lw-over-btn{margin-top:8px;width:100%;padding:8px;border-radius:6px;border:1px solid #6a4fb0;background:#241433;color:#e7d7f5;cursor:pointer;font-weight:bold;}#lw-over-btn:disabled{opacity:.4;cursor:not-allowed;}#lw-btns{display:flex;gap:8px;margin-top:8px;}#lw-btns button{flex:1;padding:8px 6px;border-radius:6px;border:1px solid #2e7d32;background:#103a1e;color:#d7f5dd;cursor:pointer;font-size:12.5px;}#lw-btns button:hover{background:#1a5630;}</style><div id="lw-wrap"><div id="lw-stage"><div id="lw-ring"></div><div id="lw-core" title="菲利希亚"></div></div><div id="lw-side"><div id="lw-bar"><div class="pill">回响 <b>'+echo+'</b></div><div class="pill">今日苏醒 <b>'+n+'</b>/3</div></div><div id="lw-info">'+help+'</div><button id="lw-over-btn" disabled>先点选一位沉睡的先祖</button><div id="lw-btns"><button data-act="commune">🌿 通灵（长休后随机）</button><button data-act="offer">🕯️ 祭祀先祖（长休时）</button></div></div></div>';
  const dlg=new Dialog({title:"破碎循环的月桂 · 群灵议会",content:html,buttons:{close:{label:"关闭"}},default:"close",render:(h)=>{
    const root=h[0]||h;const dr=getDraw(actor),ov=getOver(actor);
