    function statusOf(e){return dr.includes(e.code)?'<span style="color:#5dff8f;">● 已苏醒</span>':(ov.includes(e.code)?'<span style="color:#c4a9ff;">✦ 越界唤起中</span>':'<span style="color:#7fae8b;">○ 沉睡</span>');}
    function selectDot(e,el){if(selEl)selEl.classList.remove("lw-sel");selEl=el;if(el)el.classList.add("lw-sel");selected=e;
      info.innerHTML='<h3>'+e.code+'·'+e.name+'</h3><div class="ttl">'+(e.en||'')+' · '+statusOf(e)+'</div><div class="body">'+cleanRoll(e.desc)+'</div>';
      const callable=!dr.includes(e.code)&&!ov.includes(e.code);overBtn.disabled=!callable;
      overBtn.textContent=callable?("越界召唤 "+e.code+"·"+e.name+"（附赠动作 · 回响+1）"):"该先祖已在场，无需越界";}
    entries.forEach((e,i)=>{const ang=(i/entries.length)*2*Math.PI-Math.PI/2,x=cx+R*Math.cos(ang),y=cy+R*Math.sin(ang);
      const w=document.createElement("div");w.className="lw-wrap";w.style.left=x+"px";w.style.top=y+"px";
      const dx=(Math.random()*2-1)*7,dy=(Math.random()*2-1)*7,dur=(4+Math.random()*4).toFixed(2);
